-- Save MJ: Actions (core SP call only)
DECLARE @Description_b7d4acacfbdb NVARCHAR(MAX),
@ID_b7d4acacfbdb UNIQUEIDENTIFIER
SET
  @Description_b7d4acacfbdb = N'Pull messages and calendar items for every Active-or-Error activity-sync connection and file the relevant ones as Activities. Downstream apps enrich in-stream via ActivitySyncExtension; they do not own this trigger. Idempotent: re-running over the same window writes nothing new. Run by hand with DryRun to preview what each connection would file, Paused connections included, without writing an Activity or moving a watermark.'
SET
  @ID_b7d4acacfbdb = 'B2CAEFB7-60FD-41FF-8B12-DB908A7BEF0E' EXEC [${mjSchema}].spUpdateAction @Description = @Description_b7d4acacfbdb,
  @ID = @ID_b7d4acacfbdb;

